if (out.subflow_list && hdr.num_subflows > 0 && hdr.size_kernel > 0) {
    size_t base = hdr.size_subflow_data;
    size_t step = std::min<size_t>(hdr.size_kernel, hdr.size_user);
    for (uint32_t i = 0; i < hdr.num_subflows; ++i) {
        size_t off = base + static_cast<size_t>(i) * hdr.size_user;
        if (off + step > buf.size()) break;
        struct tcp_info ti {};
        memcpy(&ti, buf.data() + off, std::min(step, sizeof ti));
        SubflowStat s;
        s.srtt_us    = ti.tcpi_rtt;
        s.cwnd       = ti.tcpi_snd_cwnd;
        s.mss        = ti.tcpi_snd_mss;
        s.retrans    = ti.tcpi_total_retrans;
        s.bytes_sent = ti.tcpi_bytes_acked;
        s.bytes_recv = ti.tcpi_bytes_received;
        s.tcp_state  = ti.tcpi_state;
        s.rto_retrans = ti.tcpi_retransmits;
        if (ti.tcpi_state == kTcpEstablished) ++out.established;

Frame msg;
msg.hdr     = f.hdr;
msg.hdr.seq = cs->asm_seq;
msg.payload.swap(cs->asm_buf);
cs->asm_active = false;

size_t app_len = msg.payload.size();
// A broadcast the channel doesn't accept is dropped here, after reassembly -- it still
// counts as delivered, so the resume offset stays on message boundaries
if (!drop_broadcast(*cs, msg) && !deliver_data(*cs, msg, link_epoch)) {
    // Not delivered: the connection was replaced (or the session closed) while the queue
    // was full. Not counted either -- the peer resends it after the resume
    return;
}
// Only advance once the whole message has been delivered, so resume_offset
// always lands on a message boundary
delivered_bytes_ += app_len;
LOG_TRACE("delivered ch=%u seq=%llu len=%zu delivered=%llu", msg.hdr.channel,
          (unsigned long long)msg.hdr.seq, app_len,
          (unsigned long long)delivered_bytes_.load());

// Summed as per-subflow deltas (keyed by the 4-tuple), not as a per-path total: the
// set of subflows changes -- a closed one (tcp_state 7) lingers in the list, then
// drops out; a new one starts from 0 -- and a total jumps when it does.
MptcpInfo mi = e->session->mptcp_info();
std::map<int, std::pair<uint64_t, uint64_t>> sf_delta;    // path -> {sent, recv} since last STAT
std::map<int, std::pair<uint32_t, uint32_t>> sf_detail;   // path -> {cwnd, srtt}
std::map<std::string, std::pair<uint64_t, uint64_t>> sf_now;
std::set<int> sf_established;   // paths with an established subflow (C41)
constexpr uint8_t kEstablished = 1;
for (const auto& sf : mi.subflow) {
    const std::string key = sf.local_addr + ":" + std::to_string(sf.local_port) + ">" +
                            sf.remote_addr + ":" + std::to_string(sf.remote_port);
    sf_now[key] = {sf.bytes_sent, sf.bytes_recv};
    if (sf.path_id < 0) continue;
    uint64_t ps = 0, pr = 0;   // a subflow first seen now: all its bytes are new
    auto     pit = e->prev_subflow_bytes.find(key);
    if (pit != e->prev_subflow_bytes.end()) std::tie(ps, pr) = pit->second;
    auto& d = sf_delta[sf.path_id];
    d.first += sf.bytes_sent > ps ? sf.bytes_sent - ps : 0;
    d.second += sf.bytes_recv > pr ? sf.bytes_recv - pr : 0;
    // Detail fields come from the most active established subflow on this path
    if (sf.tcp_state != kEstablished) continue;
    sf_established.insert(sf.path_id);
    auto& det = sf_detail[sf.path_id];
    if (sf.bytes_sent + sf.bytes_recv > 0 || det.first == 0) det = {sf.cwnd, sf.srtt_us};
}
e->prev_subflow_bytes.swap(sf_now);

