// Which path carries the data: the one with most of it, over 1 Mbit/s, for two samples in a
// row (a primary / backup failover shows as the data moving; mpxd's own event is the UE's)
function trackCarrier(s) {
  // mpxd >= C41 says which paths have an established data subflow: the carrier is a usable
  // primary with one, else a backup with one; none while every path is down. At once, exact --
  // the throughput lags (video comes in bursts) and stays on a path that went down.
  if (s.paths.some((p) => p.data_subflow !== undefined)) {
    const usable = s.paths.filter((p) => p.data_subflow && (p.state === "up" || p.state === "degraded"));
    const pick = usable.find((p) => !p.backup) || usable[0];
    const now = pick ? pick.link : null;
    if (now !== null && carrying !== null && now !== carrying)
      addEvent(s.ts_ms / 1000, "data_moved", `Data moved to ${pathFull(now)} (${now})`, "subflows", now);
    carrying = now;
    return;
  }
  let best = null, bestRate = 1;
  for (const p of s.paths) if (rateOf(p) > bestRate) { best = p.link; bestRate = rateOf(p); }
  if (best === null || best === carrying) { carryCount = 0; return; }
  if (++carryCount < 2) return;
  if (carrying !== null) addEvent(s.ts_ms / 1000, "data_moved", `Data moved to ${pathFull(best)} (${best})`, "throughput", best);
  carrying = best;
  carryCount = 0;
}

