  if (player) {
    try {
      r = rendition(player.getQualityFor("video"));
      n = (player.getBitrateInfoListFor("video") || []).length;
      buf = player.getBufferLength("video");
      tput = player.getAverageThroughput("video");
    } catch (e) { /* not initialised yet */ }
  }
  const q = video.getVideoPlaybackQuality ? video.getVideoPlaybackQuality() : null;
  const ongoing = st.stallSince !== null && st.stallCounted ? now() - st.stallSince : 0;
  return {
    v: 1,
    ts_ms: now(),
    state: st.state,
    url: url,
    rendition: r,
    renditions: n,
